package org.example;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.ServerSocket;
import java.net.Socket;

public class App {
    private static int DEFAULT_PORT = 9999;
    private static int DEFAULT_MAX_THREADS = 10;
    private static int activeClients = 0;

    public static void main(String[] args) {
        int port = DEFAULT_PORT;
        int max_threads = DEFAULT_MAX_THREADS;

        try {
            if (args.length > 0) {
                port = Integer.parseInt(args[0]);
            }
            if (args.length > 1) {
                max_threads = Integer.parseInt(args[1]);
            }
        } catch (NumberFormatException ex) {
            System.err.println("Spatny port nebo pocet vlaken. Pouziji se vychozi hodnoty: port = " + DEFAULT_PORT + ", vlakna = " + max_threads);
        }

        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("Server bezi na portu " + port + ".");

            while (true) {
                Socket socket = serverSocket.accept();
                boolean registered = tryRegisterClient(max_threads);
                if (!registered) {
                    System.err.println("Dosazeno maximalniho poctu vlaken.");
                    discardClient(socket);
                    continue;
                }

                System.out.println("Pripojil se novy klient: " + socket.getInetAddress().getHostAddress());
                ClientHandler handler = new ClientHandler(socket);
                try {
                    handler.start();
                } catch (RuntimeException | Error e) {
                    clientDisconnected();
                    try {
                        socket.close();
                    } catch (IOException closeError) {
                        e.addSuppressed(closeError);
                    }
                    throw e;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void discardClient(Socket socket) {
        try (Socket rejectedSocket = socket;
             BufferedReader input = new BufferedReader(
                     new InputStreamReader(rejectedSocket.getInputStream()))) {
            while (input.readLine() != null) {
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static synchronized boolean tryRegisterClient(int maxClients) {
        if (activeClients >= maxClients) {
            return false;
        }
        activeClients++;
        return true;
    }

    static synchronized void clientDisconnected() {
        activeClients--;
    }
}
